    def test_bounded_startup_and_workflow_shell(self):
        source=normalize('source:Ate/App/AteApp.swift', (ROOT/'Ate/App/AteApp.swift').read_text()).split('enum StartupLivenessDiagnostic {')[1]
        for token in ['rows.count < 28','schedulerRows.count < 12','-qaStartupLivenessDiagnostic','AppConfig.isUITesting','180, 240','scheduler-main-delivery']:
            self.assertIn(token,source)
        for token in ['accessibility','firstResponder','store.','Timer(']:
            self.assertNotIn(token,source)
        for file in ['compile-check.yml','dogfood-qualification.yml']:
            workflow=yaml.safe_load((ROOT/'.github/workflows'/file).read_text())
            for job in workflow['jobs'].values():
                for step in job.get('steps',[]):
                    if 'startup-liveness' in step.get('run',''):
                        subprocess.run(['bash','-n'],input=step['run'],text=True,check=True)
